import networkx as nx
import json
import os
import pandas as pd
from typing import Dict, List


def search_algorithm(src, dsts, G, num_partitions):
    """Construct a minimum shared-edge directed Steiner broadcast tree, using greedy growth only for very large destination sets."""
    import heapq

    h = G.copy()
    h.remove_edges_from(list(h.in_edges(src)) + list(nx.selfloop_edges(h)))
    topology = BroadCastTopology(src, dsts, num_partitions)
    terminals = [dst for dst in dict.fromkeys(dsts) if dst != src]

    if not terminals:
        return topology

    # cost[mask][node] is the minimum cost of a tree rooted at node reaching
    # every terminal represented by mask.  Combining masks at a relay charges
    # the shared upstream transfer only once.
    # Fourteen terminals remains practical for the relatively small regional
    # cloud graphs while avoiding greedy plans for medium-sized broadcasts.
    if len(terminals) <= 14:
        states = 1 << len(terminals)
        cost = [dict() for _ in range(states)]
        choice = [dict() for _ in range(states)]

        for mask in range(1, states):
            initial, decisions = {}, {}

            if mask & (mask - 1) == 0:
                terminal = terminals[mask.bit_length() - 1]
                initial[terminal] = 0.0
                decisions[terminal] = ("terminal",)
            else:
                part = (mask - 1) & mask
                while part:
                    other = mask ^ part
                    if part < other:
                        for node, left in cost[part].items():
                            right = cost[other].get(node)
                            value = left + right if right is not None else float("inf")
                            if value < initial.get(node, float("inf")):
                                initial[node] = value
                                decisions[node] = ("split", part, other)
                    part = (part - 1) & mask

            cost[mask], choice[mask] = initial, decisions
            heap = [(value, node) for node, value in initial.items()]
            heapq.heapify(heap)

            # Reverse shortest paths prepend the least-cost common prefix.
            while heap:
                value, node = heapq.heappop(heap)
                if value != cost[mask].get(node):
                    continue
                for parent in h.predecessors(node):
                    edge_cost = h[parent][node].get("cost")
                    if edge_cost is None:
                        continue
                    candidate = value + edge_cost
                    if candidate < cost[mask].get(parent, float("inf")):
                        cost[mask][parent] = candidate
                        choice[mask][parent] = ("edge", node)
                        heapq.heappush(heap, (candidate, parent))

        full = states - 1
        if src not in cost[full]:
            raise nx.NetworkXNoPath("A broadcast destination is unreachable")

        selected = set()

        def collect(node, mask):
            decision = choice[mask][node]
            if decision[0] == "terminal":
                return
            if decision[0] == "edge":
                child = decision[1]
                selected.add((node, child))
                collect(child, mask)
            else:
                collect(node, decision[1])
                collect(node, decision[2])

        collect(src, full)
        tree = nx.DiGraph()
        tree.add_edges_from(selected)

        for dst in terminals:
            path = nx.shortest_path(tree, src, dst)
            edges = [[a, b, G[a][b]] for a, b in zip(path, path[1:])]
            for partition in range(num_partitions):
                topology.set_dst_partition_paths(dst, partition, edges)
        return topology

    # For larger terminal sets, use fast incremental shared-tree growth.
    reached = {src}
    source_paths = {src: [src]}
    pending = terminals

    while pending:
        distances, extensions = nx.multi_source_dijkstra(h, reached, weight="cost")
        candidates = [dst for dst in pending if dst in distances]
        if not candidates:
            raise nx.NetworkXNoPath("A broadcast destination is unreachable")

        dst = min(candidates, key=lambda node: distances[node])
        extension = extensions[dst]
        attach = extension[0]
        path = source_paths[attach] + extension[1:]

        for index, node in enumerate(extension[1:], 1):
            source_paths.setdefault(node, source_paths[attach] + extension[1:index + 1])

        reached.update(extension)
        pending.remove(dst)

        for a, b in zip(path, path[1:]):
            edge = [a, b, G[a][b]]
            for partition in range(num_partitions):
                topology.append_dst_partition_path(dst, partition, edge)

    return topology


